CREATE TABLE IF NOT EXISTS "email_analytics_settings" ("id" serial PRIMARY KEY, "organisation_id" integer NOT NULL REFERENCES "organisations"("id"), "enabled" boolean NOT NULL DEFAULT false, "contact_types" text[] NOT NULL DEFAULT ARRAY['Client','Client - Individual Tax']::text[], "workday_start_minutes" integer NOT NULL DEFAULT 570, "workday_end_minutes" integer NOT NULL DEFAULT 1050, "friday_end_minutes" integer NOT NULL DEFAULT 870, "sync_interval_minutes" integer NOT NULL DEFAULT 15, "last_mailbox_sync_at" timestamp, "last_karbon_sync_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "email_analytics_settings_organisation_key" UNIQUE ("organisation_id"));
CREATE TABLE IF NOT EXISTS "email_analytics_mailboxes" ("id" serial PRIMARY KEY, "organisation_id" integer NOT NULL REFERENCES "organisations"("id"), "address" varchar NOT NULL, "display_name" varchar, "enabled" boolean NOT NULL DEFAULT true, "graph_delta_link" text, "last_synced_at" timestamp, "last_sync_error" text, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "email_analytics_mailbox_organisation_address_key" UNIQUE ("organisation_id","address"));
CREATE TABLE IF NOT EXISTS "email_analytics_contacts" ("id" serial PRIMARY KEY, "organisation_id" integer NOT NULL REFERENCES "organisations"("id"), "karbon_contact_id" varchar NOT NULL, "name" varchar NOT NULL, "organisation_name" varchar, "email" varchar NOT NULL, "contact_type" varchar NOT NULL, "client_manager" varchar, "active" boolean NOT NULL DEFAULT true, "synced_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "email_analytics_contact_organisation_karbon_key" UNIQUE ("organisation_id","karbon_contact_id"));
CREATE INDEX IF NOT EXISTS "email_analytics_contact_email_index" ON "email_analytics_contacts" ("organisation_id","email");
CREATE TABLE IF NOT EXISTS "email_analytics_conversations" ("id" serial PRIMARY KEY, "organisation_id" integer NOT NULL REFERENCES "organisations"("id"), "subject" text, "latest_client_message_at" timestamp, "latest_mbs_response_at" timestamp, "client_contact_id" integer REFERENCES "email_analytics_contacts"("id"), "disposition" varchar, "disposition_at" timestamp, "disposition_by_user_id" integer REFERENCES "users"("id"), "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "email_analytics_conversation_groups" ("id" serial PRIMARY KEY, "organisation_id" integer NOT NULL REFERENCES "organisations"("id"), "mailbox_id" integer NOT NULL REFERENCES "email_analytics_mailboxes"("id"), "graph_conversation_id" varchar NOT NULL, "canonical_conversation_id" integer NOT NULL REFERENCES "email_analytics_conversations"("id"), "created_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "email_analytics_group_mailbox_conversation_key" UNIQUE ("mailbox_id","graph_conversation_id"));
CREATE TABLE IF NOT EXISTS "email_analytics_messages" ("id" serial PRIMARY KEY, "organisation_id" integer NOT NULL REFERENCES "organisations"("id"), "mailbox_id" integer NOT NULL REFERENCES "email_analytics_mailboxes"("id"), "canonical_conversation_id" integer NOT NULL REFERENCES "email_analytics_conversations"("id"), "graph_message_id" varchar NOT NULL, "graph_conversation_id" varchar, "internet_message_id" varchar, "direction" varchar NOT NULL, "sender_email" varchar, "sender_name" varchar, "subject" text, "web_link" text, "received_at" timestamp NOT NULL, "created_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "email_analytics_message_mailbox_graph_key" UNIQUE ("mailbox_id","graph_message_id"));
CREATE INDEX IF NOT EXISTS "email_analytics_message_internet_id_index" ON "email_analytics_messages" ("organisation_id","internet_message_id");
CREATE INDEX IF NOT EXISTS "email_analytics_message_canonical_index" ON "email_analytics_messages" ("canonical_conversation_id","received_at");
CREATE TABLE IF NOT EXISTS "email_analytics_disposition_audit" ("id" serial PRIMARY KEY, "organisation_id" integer NOT NULL REFERENCES "organisations"("id"), "canonical_conversation_id" integer NOT NULL REFERENCES "email_analytics_conversations"("id"), "previous_disposition" varchar, "disposition" varchar, "action" varchar NOT NULL, "performed_by_user_id" integer NOT NULL REFERENCES "users"("id"), "performed_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "email_analytics_sync_runs" ("id" serial PRIMARY KEY, "organisation_id" integer NOT NULL REFERENCES "organisations"("id"), "kind" varchar NOT NULL, "status" varchar NOT NULL, "attempts" integer NOT NULL DEFAULT 0, "error" text, "started_at" timestamp NOT NULL DEFAULT now(), "completed_at" timestamp);